SELECT  COUNT(*) AS NUM,DATE_FORMAT(create_time_,'%Y') AS DAYS, create_time_,CREATE_BY_,shop FROM crmp_vip_card  where 1=1 
/*CONDITION*/
 GROUP BY  DAYS ORDER BY DAYS DESC limit 5

/* ApplicationName=DBeaver 25.3.4 - SQLEditor <Script-41.sql> */  SELECT t.id, jt.order_no
FROM pur_order_item t
JOIN JSON_TABLE(
  JSON_KEYS(t.order_info),
  '$[*]' COLUMNS (order_no VARCHAR(64) PATH '$')
) jt

select a.SHOP,a.IDNO,ifnull(a.name,a.NICKNAME) as name,a.ID_,b.ID_ AS VIPID,a.SEX_NAME,a.PHONE,b.CARD_NO,b.TYPE_NAME ,b.LEVEL,b.LEVEL_NAME,a.create_time_,a.sex,a.birthday,b.`LEVEL`,p.use_thispoints,ROUND(DATEDIFF(CURDATE(),a.birthday)/365.2422) as age
from crmp_vip_info a   left join crmp_vip_card b on a.ID_=b.REF_ID_ left join crmp_vip_points p on a.ID_=p.vipid WHERE 1=1 and b.status='1' AND ((PHONE like '%%13712473965%%'))
 LIMIT 10

select contract_status,sum(if(a.iscontract=1,1,0)) as must_contract,sum(if(a.contract_status>0,1,0)) as contract_num ,sum(if(e.status=3,1,0)) as yes_contract_num from evt_meals_person m  left join evt_person a on a.id=m.person_id left join evt_meals_person mp on mp.pid=m.id left join evt_meals ms on ms.id=m.meals_id left join evt_contract e on (a.contract_status=e.id) where a.mark=1 and ms.mark = 1 and (UNIX_TIMESTAMP(m.start_date) <= 1774886400 or (ms.monthly_billing_method = 2 and 
            CASE WHEN day(m.start_date) < day(FROM_UNIXTIME(ms.starttime)) THEN UNIX_TIMESTAMP(DATE_SUB(m.start_date, INTERVAL 1 MONTH))  <= 1774886400 ELSE UNIX_TIMESTAMP(m.start_date) <= 1774886400 END 
            )) and m.type = 1 and (m.status in (1,3,4,5,6,7) or m.status in (8,10)) and m.mark = 1 and (m.customer_id in (109710,113300,112692,112503,112103,112101,111435,111056,110646,110645,110644,110643,110642,110641,110640,110639,110638,110637,110636,110635,109712,109711)) and m.signing_id = 219 group by a.customer_id

SELECT COUNT(*) as count FROM (select count(*) as count0 from evt_meals_person m  left join evt_person a on a.id=m.person_id left join evt_meals_person mp on mp.pid=m.id left join evt_meals ms on ms.id=m.meals_id where a.mark=1 and ms.mark = 1 and (UNIX_TIMESTAMP(m.start_date) <= 1772467200 or (ms.monthly_billing_method = 2 and 
            CASE WHEN day(m.start_date) < day(FROM_UNIXTIME(ms.starttime)) THEN UNIX_TIMESTAMP(DATE_SUB(m.start_date, INTERVAL 1 MONTH))  <= 1772467200 ELSE UNIX_TIMESTAMP(m.start_date) <= 1772467200 END 
            )) and m.type = 1 and (m.status in (1,3,4,5,6,7) or m.status in (8,10)) and m.mark = 1 and (m.customer_id in (113096)) and m.signing_id = 80 group by m.id) aa
